{"path":"src/cache.ts","content":"import type { User } from "./api.ts";
import { loadUser } from "./api.ts";

export type Loader = typeof loadUser;

const cache = new Map<number, User | undefined>();

export function fetchUserCached(id: number, load: Loader = loadUser): User | undefined {
  if (!cache.has(id)) cache.set(id, load(id));
  return cache.get(id);
}

export const fetchUserCacheSize = (): number => cache.size;
